import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"安全启动与签名","description":"","frontmatter":{"title":"安全启动与签名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/secure-boot.md","filePath":"cs/secure-boot.md","lastUpdated":1789023840000}'),h={name:"cs/secure-boot.md"};function u(m,a,_,f,E,b){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="安全启动与签名" tabindex="-1">安全启动与签名 <a class="header-anchor" href="#安全启动与签名" aria-label="Permalink to &quot;安全启动与签名&quot;">​</a></h1><div class="epigraph"><p>UEFI Secure Boot 用密钥验证引导加载器与内核签名，使未授权映像不能在这条链上启动——除非密钥被你或厂商控制。</p><footer>—— 据 UEFI 规范对 Secure Boot 的说明；Linux 对内核模块签名与 MOK 的文档</footer></div><p><a href="/cs/kernel-audit">audit</a> 记运行时。<a href="/cs/kernel-hardening">加固</a> 假定内核是真的。缺口是 <strong>启动时验证映像</strong>：shim、MOK、与模块签名后课的分工点到启动链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>恶意 bootloader 可在 LSM 之前赢。Secure Boot：固件用 PK/KEK/db 验签名。Linux：shim 验 grub/内核；用户 MOK 管自签。缺口：禁用 SB 的机器没有这条保证；密钥吊销 dbx。本课不把如何关 SB 当教程。</p><p><span class="marginnote">签名的是 PE/EFI 或内核镜像，不是 rootfs 全文——rootfs 要 dm-verity 等另一层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>上电 → 固件验 boot 应用 → 验内核 → 启动。对照 <a href="/cs/dm-crypt">dm-crypt</a>：加密防读，签名防改启动代码。对照 LSM：时间上签名更早。对照 <a href="/cs/fuse">FUSE</a>：无关。</p>',8)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FW%5B%22UEFI%20%E5%AF%86%E9%92%A5%E5%BA%93%22%5D%20--%3E%20SHIM%5B%22%E9%AA%8C%20shim%22%5D%0A%20%20SHIM%20--%3E%20KERN%5B%22%E9%AA%8C%E5%86%85%E6%A0%B8%22%5D%0A%20%20KERN%20--%3E%20INIT%5B%22initramfs%20%E4%BB%8D%E9%9C%80%E5%8F%A6%E9%AA%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全启动把信任锚放到固件密钥，缩小「任意内核」攻击。锚被控则链无意义。不要写成 TPM 全文——下一课度量。与 <a href="/cs/linux-capabilities">capabilities</a>：启动后才有进程。</p><p>发行版密钥与用户 MOK 的冲突是运维日常。</p><p>实现上：shim 的 MOK 让用户加自己的密钥，也让恶意者在已解锁机器上加密钥。内核签名过了不等于 initramfs 里的脚本可信，还要单独量。 读法上只引用<a href="/cs/kernel-audit">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>安全启动与签名</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每家 OEM 的定制。不保证嵌入式 ROM 引导同构。下一课 TPM 度量启动。</p><p>版本字段会变，课序钉的是机制对象「安全启动与签名」，不是某一主线内核的结构体名。 后课默认：引导映像可被固件验签。PCR 度量链，下一课 TPM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Secure Boot 验引导链签名。</li><li>不自动验证整个根文件系统。</li><li>TPM 度量是下一课。</li><li>出处：UEFI；Linux Secure Boot；shim/MOK。</li></ul>',11))])}const T=i(h,[["render",u]]);export{A as __pageData,T as default};
